#define MAX_N 100
int stack[MAX_N];
int top = -1;
void push(int val) {stack[++top] = val;}
int pop() {return stack[top--];}
int fib(int n) {
    if (n == 0) return 0;
    if (n == 1) return 1;
    push(0);  // fib(0)
    push(1);  // fib(1)
    for (int i = 2; i <= n; i++) {
        int b = pop();    // fib(i-1)
        int a = pop();    // fib(i-2)
        int c = a + b;    // fib(i)
        push(b);          // 再び使うため
push(c);          // 最新のfib(i)
    }
    return pop();  // fib(n)}
